/**
 * Worklet backend switch — the only place worklet-engine.ts should import from.
 *
 * Source-tree default: pure JS (safe for `deno task build:js` and normal dev).
 * WASM bundles do NOT edit this file; build.ts aliases the resolve to
 * worklet-backend-wasm.ts via esbuild plugin.
 *
 * Future SIMD / thread variants: add worklet-backend-wasm-simd.ts etc. and
 * point the corresponding build target alias at them.
 *
 * API contract (all backends must export):
 *   - createWorkletModuleURL(): string
 *   - postInitToWorklet(node: AudioWorkletNode): void
 *   - MIDY_WORKLET_NAME, WORKLET_MAX_VOICES
 */

export {
  createWorkletModuleURL,
  MIDY_WORKLET_NAME,
  WORKLET_MAX_VOICES,
} from "./worklet-processor.ts";

/** No-op for pure JS. WASM backend posts the module bytes after node creation. */
export function postInitToWorklet(_node: AudioWorkletNode): void {
  // intentionally empty
}
